import { catalog } from "./catalog.js";
import { BRANDS } from "./brands.js";
import { TONES } from "../lib/kelvin.js";
import { normalizeOption } from "../lib/specSummary.js";
// How cleanly each model's primary photo reads as a product on white,
// rather than a carton or a marketing panel. Generated by sampling every
// primary image once; regenerate if the catalogue's photography changes.
// Keyed by raw product id — brands without scores fall back to the primary
// image, which is the default anyway.
import imageScores from "./imageScores.json";

// The whole catalogue, already normalised in catalog.js. When the live API
// lands, swap the glob loader there for a fetch — nothing below this line,
// nor any page, needs to change.
export const products = catalog;

export function getCategories() {
  return [...new Set(products.map((p) => p.category))];
}

export function getProductsByCategory(category) {
  if (!category) return products;
  return products.filter(
    (p) => p.category.toLowerCase() === category.toLowerCase(),
  );
}

// Unique subcategories for a category, each paired with a model count and
// a representative image. Whichever model in the type photographs best
// stands for it — the first one listed is often a carton or a poster.
// See imageScores.json for how "best" is measured.
export function getSubcategories(category) {
  const items = getProductsByCategory(category);
  const map = new Map();
  for (const p of items) {
    if (!p.subcategory) continue;
    const entry = map.get(p.subcategory);
    const score = imageScores[p.id] ?? -99;
    if (entry) {
      entry.count += 1;
      if (score > entry.score) {
        entry.score = score;
        entry.image = getProductImage(p);
      }
    } else {
      map.set(p.subcategory, {
        name: p.subcategory,
        image: getProductImage(p),
        score,
        count: 1,
      });
    }
  }
  return [...map.values()];
}

// The primary image is the one frame the catalogue reliably points at the
// product itself. Alternate frames were measured and rejected: many are
// marketing panels shot on white, which no cheap image metric separates
// from a real product shot.
export function getProductImage(product) {
  return product?.images?.primary;
}

// Accepts a uid ("orient--linea-tower-fan"); still resolves a bare raw id
// so the featured-model config and older links keep working.
export function getProductById(idOrUid) {
  return (
    products.find((p) => p.uid === idOrUid) ||
    products.find((p) => p.id === idOrUid)
  );
}

// 4 other products sharing a subcategory with `product`.
export function getRelatedProducts(product, count = 4) {
  if (!product) return [];
  return products
    .filter(
      (p) => p.uid !== product.uid && p.subcategory === product.subcategory,
    )
    .slice(0, count);
}

// --- Brands -----------------------------------------------------------------

function brandModelCounts(items) {
  const counts = new Map();
  for (const p of items) {
    counts.set(p.brandSlug, (counts.get(p.brandSlug) ?? 0) + 1);
  }
  return counts;
}

// Every brand with a live model count and a status. Brands with products are
// "stocked"; the rest render as "Coming soon" so the site shows its intended
// breadth before the data lands. Stocked brands sort to the front.
export function getBrands() {
  return brandsWithCounts(brandModelCounts(products));
}

export function getBrandsForCategory(category) {
  return brandsWithCounts(brandModelCounts(getProductsByCategory(category)));
}

function brandsWithCounts(counts) {
  return BRANDS.map((brand) => {
    const count = counts.get(brand.slug) ?? 0;
    return {
      ...brand,
      count,
      status: count > 0 ? "stocked" : "coming-soon",
    };
  }).sort((a, b) => b.count - a.count);
}

export function getProductsByBrand(brandSlug) {
  return products.filter((p) => p.brandSlug === brandSlug);
}

// --- Facets ---------------------------------------------------------------

const TONE_NAMES = TONES.map((t) => t.name);

// Values are counted by their normalized form so "1200MM" and "1200mm"
// are one filter, not two.
function optionValues(items, key) {
  const counts = new Map();
  for (const p of items) {
    const seen = new Set();
    for (const variant of p.variants ?? []) {
      const value = variant.options?.[key];
      if (!value || value === "Default Title") continue;
      const id = normalizeOption(value);
      if (seen.has(id)) continue;
      seen.add(id);
      counts.set(id, (counts.get(id) ?? 0) + 1);
    }
  }
  return counts;
}

function leadingNumber(value) {
  const match = String(value).match(/[\d.]+/);
  return match ? Number(match[0]) : Number.POSITIVE_INFINITY;
}

// Fans are specified by sweep and finish; lighting by wattage and tone.
// The filter panel is built from whichever spec a category actually
// carries, so the controls speak the same language as the products. The
// brand facet leads when more than one brand stocks the category.
export function getFacets(category) {
  const items = getProductsByCategory(category);
  const facets = [];

  const brandCounts = brandModelCounts(items);
  if (brandCounts.size > 1) {
    facets.push({
      key: "__brand",
      id: "brand",
      label: "Brand",
      kind: "chip",
      values: [...brandCounts.entries()]
        .map(([slug, count]) => ({
          value: slug,
          label: BRANDS.find((b) => b.slug === slug)?.name ?? slug,
          count,
        }))
        .sort((a, b) => b.count - a.count),
    });
  }

  const tones = optionValues(items, "Color");
  const availableTones = TONE_NAMES.filter((name) =>
    tones.has(normalizeOption(name)),
  );
  if (availableTones.length > 1) {
    facets.push({
      key: "Color",
      id: "tone",
      label: "Light tone",
      kind: "tone",
      values: availableTones.map((name) => ({
        value: name,
        count: tones.get(normalizeOption(name)),
      })),
    });
  }

  const wattage = optionValues(items, "Wattage");
  if (wattage.size > 1) {
    facets.push({
      key: "Wattage",
      id: "wattage",
      label: "Wattage",
      kind: "chip",
      values: [...wattage.entries()]
        .sort((a, b) => leadingNumber(a[0]) - leadingNumber(b[0]))
        .map(([value, count]) => ({ value, count })),
    });
  }

  const size = optionValues(items, "Size");
  if (size.size > 1) {
    facets.push({
      key: "Size",
      id: "size",
      label: category?.toLowerCase() === "fans" ? "Sweep" : "Size",
      kind: "chip",
      values: [...size.entries()]
        .sort((a, b) => leadingNumber(a[0]) - leadingNumber(b[0]))
        .map(([value, count]) => ({ value, count })),
    });
  }

  return facets;
}

export function hasOptionValue(product, key, value) {
  if (key === "__brand") return product.brandSlug === value;
  const wanted = normalizeOption(value);
  return (product.variants ?? []).some(
    (v) => v.options?.[key] && normalizeOption(v.options[key]) === wanted,
  );
}

// Catalogue photography is uneven: many frames are the retail carton, and
// most in-room shots have marketing copy burned into them. These three
// slots are large enough that the photo has to be right, so each names a
// model and a frame checked by eye. Everything else uses the primary
// image, which is reliable at card size.
const FEATURED = {
  hero: { id: "raya-curve-wall-light", frame: 1 },
  fans: {
    id: "ecotech-air-bldc-ceiling-fan-with-remote-5-star-powerful-airflow-380-rpm",
    frame: 0,
  },
  lighting: { id: "raya-candle-wall-light", frame: 0 },
};

function resolveFeatured(slot, fallbackCategory) {
  const pick = FEATURED[slot];
  const product = pick && getProductById(pick.id);
  if (product) {
    const image =
      product.images?.gallery?.[pick.frame] ?? product.images?.primary;
    return { product, image };
  }

  // The named model is gone — fall back to the largest type in the category.
  const items = getProductsByCategory(fallbackCategory);
  const largest = getSubcategories(fallbackCategory).sort(
    (a, b) => b.count - a.count,
  )[0];
  const substitute =
    items.find((p) => p.subcategory === largest?.name) ?? items[0];
  return { product: substitute, image: substitute?.images?.primary };
}

export function getHeroFeature() {
  return resolveFeatured("hero", "Lighting");
}

export function getCategoryFeature(category) {
  return resolveFeatured(category?.toLowerCase(), category);
}

// One well-photographed model per subcategory, across whatever brands exist,
// for the homepage hero. Ordered so fans and lighting interleave rather than
// clumping.
export function getShowcaseProducts() {
  const byType = new Map();
  for (const p of products) {
    if (!p.subcategory || !getProductImage(p)) continue;
    const score = imageScores[p.id] ?? -99;
    const current = byType.get(p.subcategory);
    if (!current || score > current.score) {
      byType.set(p.subcategory, { product: p, score });
    }
  }

  const picks = [...byType.values()]
    .sort((a, b) => b.score - a.score)
    .map((entry) => entry.product);

  const fans = picks.filter((p) => p.category === "Fans");
  const lighting = picks.filter((p) => p.category === "Lighting");
  const interleaved = [];
  for (let i = 0; i < Math.max(fans.length, lighting.length); i += 1) {
    if (fans[i]) interleaved.push(fans[i]);
    if (lighting[i]) interleaved.push(lighting[i]);
  }
  return interleaved;
}
